import time, numpy as np, scipy.sparse as sp, scipy.sparse.linalg as spla
from reference import Task

def baseline(problem):
    A=problem['matrix']; k=problem['k']; N=A.shape[0]
    v0=np.ones(N, dtype=A.dtype)
    return spla.eigs(A,k=k,v0=v0,maxiter=N*200,ncv=max(2*k+1,20))

def alt(problem):
    A=problem['matrix']; k=problem['k']; N=A.shape[0]
    v0=np.ones(N, dtype=A.dtype)
    return spla.eigs(A,k=k,v0=v0,ncv=max(2*k+1,20))

for seed in [1,2,3,4,5]:
    prob=Task().generate_problem(n=300, random_seed=seed)
    t=time.perf_counter(); baseline(prob); t1=time.perf_counter();
    b=t1-t
    t=time.perf_counter(); alt(prob); t2=time.perf_counter();
    a=t2-t
    print(seed, b, a)
