import numpy as np, scipy.sparse as sp, scipy.sparse.linalg as spla, math, random
from reference import Task

def test_tol(tol, N=300, trials=100):
    ok=0
    for seed in random.sample(range(10**8), trials):
        prob=Task().generate_problem(n=N, random_seed=seed)
        A=prob['matrix']; k=prob['k']; Nsize=A.shape[0]; v0=np.ones(Nsize)
        try:
            vals_fast, vecs_fast=spla.eigs(A,k=k,v0=v0,maxiter=Nsize*200,ncv=max(2*k+1,20),tol=tol)
        except Exception as e:
            continue
        order_fast=np.argsort(-np.abs(vals_fast))
        vecs_fast=vecs_fast[:,order_fast]

        vals_ref, vecs_ref=spla.eigs(A,k=k,v0=v0,maxiter=Nsize*200,ncv=max(2*k+1,20),tol=0)
        order_ref=np.argsort(-np.abs(vals_ref))
        vecs_ref=vecs_ref[:,order_ref]
        good=True
        for i in range(k):
            sim=np.abs(np.dot(vecs_ref[:,i].conj()/np.linalg.norm(vecs_ref[:,i]), vecs_fast[:,i]/np.linalg.norm(vecs_fast[:,i])))
            if not math.isclose(sim,1.0,abs_tol=1e-6):
                good=False
                break
        if good:
            ok+=1
    return ok

for tol in [1e-6, 1e-7, 1e-8]:
    ok=test_tol(tol, trials=50)
    print('tol',tol,'pass', ok)
