import numpy as np, scipy.sparse as sp, scipy.sparse.linalg as spla, random, math
from reference import Task

def try_seed(seed, tol=0):
    prob=Task().generate_problem(n=300, random_seed=seed)
    A=prob['matrix']; k=prob['k']
    A32=A.astype(np.float32)
    v032=np.ones(A32.shape[0], dtype=np.float32)
    try:
        vals32, vecs32=spla.eigs(A32,k=k,v0=v032,maxiter=A32.shape[0]*200,ncv=max(2*k+1,20), tol=tol)
    except Exception as e:
        return False, 'convergence'
    idx=np.argsort(-np.abs(vals32)); vecs32=vecs32[:,idx]
    # compute reference float64 for verify
    vals_ref, vecs_ref=spla.eigs(A,k=k,v0=np.ones(A.shape[0]),maxiter=A.shape[0]*200,ncv=max(2*k+1,20))
    idxr=np.argsort(-np.abs(vals_ref)); vecs_ref=vecs_ref[:,idxr]
    for i in range(k):
        sim=abs(np.dot(vecs_ref[:,i].conj()/np.linalg.norm(vecs_ref[:,i]), vecs32[:,i]/np.linalg.norm(vecs32[:,i])))
        if not math.isclose(sim, 1.0, abs_tol=1e-6):
            return False, sim
    return True, None

for tol in [1e-4, 1e-5, 1e-6, 1e-7, 1e-8]:
    fails=0; total=50
    for seed in random.sample(range(10**6), total):
        ok,_=try_seed(seed, tol=tol)
        if not ok:
            fails+=1
    print('tol',tol,'fails',fails)
